package main
type N int
func (n *N) Set(v int) int {old:=int(*n); *n=N(v);return old}
func (n N) Copy(v int) int {n=N(v);return int(n)}
func update(a,b *int) int {*a=5;*b=7;return *a}
func captured() int {n:=N(2);f:=n.Set;n=4;k:=f(8);return 10*k+int(n)}
func expression() int {n:=N(2);f:=(*N).Set;k:=f(&n,9);return 10*k+int(n)}
func copy() int {n:=N(2);f:=(*N).Copy;k:=f(&n,9);return 10*k+int(n)}
func aliases() int {x,y:=1,2;k:=update(&x,&x);return 100*k+10*x+y}
func independent() int {x,y:=1,2;k:=update(&x,&y);return 100*k+10*x+y}
func uncertain() int {n:=N(2);f:=n.Set;return f(8)+int(n)}
func post() int {n:=0;for i:=0;i<3;i++ {n=n*10+i};return n}
func none() int {n:=7;for i:=3;i<3;i++ {n=n*10+i};return n}
func forever() int {n:=0; for n>=0 {n=0};return n}
